// src/features/tasks/use-task-count.ts
import { collection, getCountFromServer, getFirestore } from '@react-native-firebase/firestore';

/** Planted: a feature reads Firestore directly instead of through the task store port. */
export async function taskCount(uid: string): Promise<number> {
  const snapshot = await getCountFromServer(collection(getFirestore(), 'users', uid, 'tasks'));
  return snapshot.data().count;
}

// src/services/sync/firestore-sync-adapter.ts
import { getFirestore, waitForPendingWrites } from '@react-native-firebase/firestore';

/** Planted: an adapter outside the declared adapter folder. */
export async function flushTasks(): Promise<void> {
  await waitForPendingWrites(getFirestore());
}

// src/services/session/async-session-adapter.ts
import AsyncStorage from '@react-native-async-storage/async-storage';

/** Planted: device-only data in AsyncStorage next to the synced store and kv-store. */
export async function saveSession(json: string): Promise<void> {
  await AsyncStorage.setItem('session', json);
}

// src/services/session/mmkv-session-adapter.ts
import { createMMKV } from 'react-native-mmkv';

/** Planted: a second key-value store. */
export const session = createMMKV();

// src/features/tasks/use-draft.ts
import Storage from 'expo-sqlite/kv-store';

/** Planted: a feature reads the key-value store without its port. */
export function readDraft(): string | null {
  return Storage.getItemSync('task-draft');
}

// src/data/firestore/presence-adapter.ts
import { getDatabase, ref, set } from '@react-native-firebase/database';

/** Planted: a second synced store (Realtime Database) beside Firestore. */
export async function markOnline(uid: string): Promise<void> {
  await set(ref(getDatabase(), `presence/${uid}`), true);
}

// src/data/firestore/local-cache.ts
import { openDatabaseSync } from 'expo-sqlite';

/** Planted: an SQLite database under mode synced (no migrations, no fixtures checked). */
export const cache = openDatabaseSync('cache.db');

// src/data/firestore/firestore-task-adapter.test.ts
import { writeBatch } from '@react-native-firebase/firestore';

import { createFirestoreTaskAdapter } from './firestore-task-adapter';

test('a save is one batch', () => {
  createFirestoreTaskAdapter('u1').saveTask({ id: 't1', listId: 'l1', title: 'Buy milk', done: false });
  expect(writeBatch).toHaveBeenCalledTimes(1);
});

// test/firestore/seed-tasks.ts
import { doc, getFirestore, setDoc } from '@react-native-firebase/firestore';

export async function seedTask(uid: string): Promise<void> {
  await setDoc(doc(getFirestore(), 'users', uid, 'tasks', 't1'), { title: 'Buy milk' });
}

import { getFirestore } from '@react-native-firebase/firestore';
import AsyncStorage from '@react-native-async-storage/async-storage';
export { AsyncStorage, getFirestore };
